-- Local-only PGlite fixtures. No hosted API or Realtime service is used here.
begin;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;if actual<>code then raise exception 'FAIL expected %, got %: %',code,actual,q;end if;return;end;raise exception 'FAIL expected rejection: %',q;end;$$;
insert into auth.users(id) values('d1000000-0000-4000-8000-000000000001'),('d1000000-0000-4000-8000-000000000002'),('d1000000-0000-4000-8000-000000000003');
update public.user_roles set role='tailor' where user_id='d1000000-0000-4000-8000-000000000003';
create function pg_temp.chat_request(n integer) returns uuid language sql as $$ select ('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
create function pg_temp.chat_message(n integer) returns uuid language sql as $$ select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
create function pg_temp.chat_send(n integer,body text default 'A plain text message',r integer default 1) returns public.request_messages language sql as $$ select public.send_request_message(pg_temp.chat_message(n),pg_temp.chat_request(r),body) $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.initialize_tailor_profile();
select public.save_tailor_profile('{"shop_name":"Chat Atelier","description":"Bespoke garments for special occasions.","specialties":"Dresses","city":"Colombo","public_address":"123 Public Street","business_phone":"+94112223344","years_experience":5,"accepting_requests":true}',true,1);
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000001',true);
do $$begin for i in 1..5 loop perform public.send_tailoring_request(pg_temp.chat_request(i),'50000000-0000-4000-8000-000000000002','dress','Please discuss this tailoring request.',1,current_date+30);end loop;end;$$;
select pg_temp.expect_error($q$select pg_temp.chat_send(1,E' \n\t ' )$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.chat_send(1,repeat('x',2001))$q$,'22023');
select pg_temp.expect_error('select pg_temp.chat_send(1,null)','22023');
select pg_temp.expect_error('select pg_temp.chat_send(1,chr(160)||chr(65279))','22023');
savepoint maximum_length;
select pg_temp.chat_send(999,repeat(chr(128512),2000));
select pg_temp.assert_true((select char_length(body)=2000 from public.request_messages where id=pg_temp.chat_message(999)),'2,000 Unicode code points are accepted');
rollback to savepoint maximum_length;
release savepoint maximum_length;
select pg_temp.chat_send(1,E'  Hello tailor \n');
select pg_temp.chat_send(1,'Hello tailor');
select pg_temp.chat_send(1,chr(160)||'Hello tailor'||chr(65279));
select pg_temp.assert_true((select count(*)=1 and bool_and(body='Hello tailor' and sender_id=auth.uid() and created_at is not null and sequence=1) from public.request_messages),'server sender/time/sequence, trimmed text and exact retry');
select pg_temp.expect_error($q$select pg_temp.chat_send(1,'Different')$q$,'22023');
select pg_temp.expect_error($q$select pg_temp.chat_send(1,'Hello tailor',2)$q$,'22023');
do $$declare before_row jsonb;after_row jsonb;begin
 select to_jsonb(r) into before_row from public.tailoring_requests r where id=pg_temp.chat_request(1);
 perform pg_temp.chat_send(2,'<script>alert(1)</script> is stored as literal plain text.');
 select to_jsonb(r) into after_row from public.tailoring_requests r where id=pg_temp.chat_request(1);
 perform pg_temp.assert_true(before_row=after_row,'messaging never updates request dates, version, quotation agreements or work stages');
 for i in 3..35 loop perform pg_temp.chat_send(i,'Message '||i);end loop;
end;$$;
select pg_temp.assert_true((select unread=0 and latest_sequence=35 from public.request_message_summaries(array[pg_temp.chat_request(1)])),'no unread or self-notification for own messages');
select pg_temp.assert_true((select count(*)=0 from public.request_notifications),'no self alerts');
select pg_temp.expect_error('update public.request_messages set body=''edited''','42501');
select pg_temp.expect_error('delete from public.request_messages','42501');
select pg_temp.expect_error($q$insert into public.request_messages(id,request_id,sequence,sender_id,body) values(gen_random_uuid(),pg_temp.chat_request(1),999,auth.uid(),'forged')$q$,'42501');
select pg_temp.expect_error('insert into public.request_message_reads values(pg_temp.chat_request(1),auth.uid(),999,now())','42501');
select pg_temp.chat_send(101,'Before rejection',3);select pg_temp.chat_send(102,'Before cancellation',4);select pg_temp.chat_send(103,'Before completion',5);
select public.decide_tailoring_request(pg_temp.chat_request(4),'cancelled','',1);
select pg_temp.expect_error('select pg_temp.chat_send(202,''After cancellation'',4)','22023');
select pg_temp.chat_send(102,'Before cancellation',4);
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select unread=35 from public.request_message_summaries(array[pg_temp.chat_request(1)])),'addressed tailor unread count');
select public.mark_request_messages_read(pg_temp.chat_request(1),10);
select public.mark_request_messages_read(pg_temp.chat_request(1),3);
select pg_temp.assert_true((select unread=25 and last_read_sequence=10 from public.request_message_summaries(array[pg_temp.chat_request(1)])),'read position is monotonic across stale tabs');
select pg_temp.expect_error('select public.mark_request_messages_read(pg_temp.chat_request(1),999)','22023');
select pg_temp.chat_send(36,'Tailor reply');
select pg_temp.expect_error('select pg_temp.chat_send(1,''Hello tailor'')','22023');
select public.decide_tailoring_request(pg_temp.chat_request(2),'accepted','',1);
select pg_temp.chat_send(104,'Accepted work can be discussed',2);
select public.decide_tailoring_request(pg_temp.chat_request(3),'rejected','Cannot take this request.',1);
select pg_temp.expect_error('select pg_temp.chat_send(201,''After rejection'',3)','22023');
select public.decide_tailoring_request(pg_temp.chat_request(5),'accepted','',1);
reset role;
update public.tailoring_requests set completed_at=clock_timestamp() where id=pg_temp.chat_request(5);
-- Stable keyset ordering even when every timestamp is identical.
update public.request_messages set created_at='2026-10-29 00:00:00Z' where request_id=pg_temp.chat_request(1);
set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000001',true);
select pg_temp.expect_error('select pg_temp.chat_send(203,''After completion'',5)','22023');
select pg_temp.chat_send(103,'Before completion',5);
select pg_temp.assert_true((select count(*)=1 from public.request_messages where request_id=pg_temp.chat_request(5)),'completed history is retained and exact retries stay safe');
select pg_temp.assert_true((select array_agg(sequence order by sequence)=array[1,2,3,4,5,6] from (select sequence from public.request_messages where request_id=pg_temp.chat_request(1) and sequence<7 order by sequence desc limit 30) page),'older-page keyset cursor excludes newer rows without timestamp ties');
select pg_temp.assert_true((select array_agg(sequence order by sequence)=array[34,35,36] from public.request_messages where request_id=pg_temp.chat_request(1) and sequence>33),'reconnect cursor recovers missed rows in order');
select pg_temp.assert_true((select unread=1 from public.request_message_summaries(array[pg_temp.chat_request(1)])),'only incoming reply is unread');
select public.mark_request_messages_read(pg_temp.chat_request(1),36);
select pg_temp.assert_true((select unread=0 from public.request_message_summaries(array[pg_temp.chat_request(1)])),'visible-read RPC clears only caller unread');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=38 from public.request_notifications where kind='message_received'),'one alert per customer message, never duplicated by retries');
select pg_temp.assert_true((select count(*)=10 from public.request_notifications where kind='message_received' and request_id=pg_temp.chat_request(1) and read_at is not null),'read cursor marks corresponding notifications only');
reset role;
-- Existing deadline/completion routines invalidate request alerts broadly. Chat alerts survive.
update public.request_notifications set invalidated_at=now() where request_id=pg_temp.chat_request(1);
select pg_temp.assert_true((select bool_and(invalidated_at is null) from public.request_notifications where kind='message_received'),'message alerts are independent of deadline invalidation');
set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.request_messages),'unrelated customer direct API cannot read');
select pg_temp.assert_true((select count(*)=0 from public.request_message_reads),'read positions are private');
select pg_temp.assert_true((select count(*)=0 from public.request_message_summaries(array[pg_temp.chat_request(1)])),'summary cannot expose unrelated request metadata');
select pg_temp.expect_error('select pg_temp.chat_send(301)','42501');
select pg_temp.expect_error('select public.mark_request_messages_read(pg_temp.chat_request(1),1)','42501');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from public.request_messages),'unaddressed tailor direct API cannot read');
select pg_temp.expect_error('select pg_temp.chat_send(302)','42501');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from public.request_messages),'admin has no participant override');
select pg_temp.expect_error('select pg_temp.chat_send(303)','42501');
reset role;set local role anon;
select pg_temp.expect_error('select * from public.request_messages','42501');
select pg_temp.expect_error('select pg_temp.chat_send(304)','42501');
reset role;rollback;
select 'PASS: request chat participants, terminal history, retries, stable pagination, read positions and notifications' as result;
